  "starter": "def minutes_to_rot(grid: list[list[int]]) -> int:\n    # Your code here\n    pass\n",
  "solution": "from collections import deque\n\ndef minutes_to_rot(grid):\n    rows, cols = len(grid), len(grid[0])\n    q = deque()\n    fresh = 0\n    for r in range(rows):\n        for c in range(cols):\n            if grid[r][c] == 2:\n                q.append((r, c))\n            elif grid[r][c] == 1:\n                fresh += 1\n    minutes = 0\n    while q and fresh:\n        for _ in range(len(q)):\n            r, c = q.popleft()\n            for i, j in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):\n                if 0 <= i < rows and 0 <= j < cols and grid[i][j] == 1:\n                    grid[i][j] = 2\n                    fresh -= 1\n                    q.append((i, j))\n        minutes += 1\n    return minutes if fresh == 0 else -1\n",
